\title{Information-Theoretic Limits of Mind Encoding:\\
Combinatorics, Incompressibility, and the Bekenstein Ceiling}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\begin{abstract}
We develop a rigorous, self-contained information-theoretic model of encoding a
neural connectome and derive four families of exact results. Modeling a mind as a
Boolean assignment over the $\binom{N}{2}$ potential synapses among $N$ neurons,
we (i) compute exact state counts for Boolean, weighted, and directed
connectomes; (ii) establish a superadditivity law for merging brains, isolating
the exact number of new cross-connections; (iii) prove a counting-based
incompressibility theorem showing that under \emph{any} injective encoding the
overwhelming majority of minds cannot receive short codewords; and (iv) combine
the quadratic slot count with the Bekenstein bound to obtain an explicit physical
ceiling $N \le 1 + \sqrt{2I}$ on the number of neurons whose connectome fits
within a region of information capacity $I$. Together these results replace
informal speculation about ``mind uploading'' with sharp, quantitative statements
about the minimum description length of a mind and the physical feasibility of
storing it.
\end{abstract}

\maketitle

\section{Introduction}

The proposition that a human mind could be ``uploaded'' --- scanned, digitized,
and stored as data --- is a recurring theme in futurism. Setting aside
neuroscience and philosophy, the proposal contains a purely mathematical core: a
mind, reduced to its connectivity structure, is a finite combinatorial object,
and storing it is an information-theoretic problem. This paper analyzes that core.

Our object of study is the \emph{connectome}: a graph on $N$ neurons in which each
potential synapse is either present or absent. We ask three questions and answer
each with a theorem: how large is the space of minds; can a mind be compressed;
and does physics permit its storage. All results are stated with proof sketches;
numbers are exact.

\section{Definitions}

Throughout, $N, M, w, B$ denote nonnegative integers, and $\binom{N}{2}$ is the
binomial coefficient counting $2$-element subsets of an $N$-element set.

\begin{definition}[Synapse slots]
The number of potential synapses among $N$ neurons --- one for each unordered
pair --- is
\[
  \mathrm{slots}(N) := \binom{N}{2} = \frac{N(N-1)}{2}.
\]
\end{definition}

\begin{definition}[Directed slots]
The number of potential \emph{directed} synapses --- one for each ordered pair of
distinct neurons --- is $\mathrm{dslots}(N) := N(N-1)$.
\end{definition}

\begin{definition}[Connectome]
A (Boolean) connectome on $N$ neurons is a function assigning a Boolean flag to
each of the $\mathrm{slots}(N)$ potential synapses; equivalently, an element of
$\{0,1\}^{\mathrm{slots}(N)}$. A $w$-weighted connectome assigns to each slot one
of $w$ weight levels, i.e.\ an element of $\{0,\dots,w-1\}^{\mathrm{slots}(N)}$.
\end{definition}

\begin{definition}[Bekenstein capacity]
For a region of radius $R$ enclosing energy $E$, with reduced Planck constant
$\hbar$ and speed of light $c$, the Bekenstein information bound, in bits, is
\[
  I(R,E) := \frac{2\pi R E}{\hbar\, c\, \ln 2}.
\]
\end{definition}

\section{State Counts}

\begin{theorem}[Boolean count]
The number of distinct connectomes on $N$ neurons is
$\bigl|\{0,1\}^{\mathrm{slots}(N)}\bigr| = 2^{\binom{N}{2}}.$
\end{theorem}
\begin{proof}
A connectome is a function from the $\mathrm{slots}(N)$ slots into a $2$-element
set; the number of such functions is $2^{\mathrm{slots}(N)} = 2^{\binom{N}{2}}$.
\end{proof}

\begin{theorem}[Weighted count]
The number of distinct $w$-weighted connectomes on $N$ neurons is $w^{\binom{N}{2}}$.
Consequently the description length of a weighted connectome is
$\binom{N}{2}\log_2 w$ bits, generalizing the Boolean bit-length ($w=2$) and
quantifying the surcharge for storing synaptic strengths rather than mere topology.
\end{theorem}
\begin{proof}
Functions from a set of size $\binom{N}{2}$ into a set of size $w$ number
$w^{\binom{N}{2}}$.
\end{proof}

\begin{theorem}[Slot doubling identity]\label{thm:double}
For all $N$, $\;2\binom{N}{2} = N(N-1) = \mathrm{dslots}(N).$
\end{theorem}
\begin{proof}
From $\binom{N}{2} = \tfrac{N(N-1)}{2}$; the product $N(N-1)$ is even, so the
halving is exact.
\end{proof}

\begin{theorem}[Directionality squares the count]
The number of directed connectomes on $N$ neurons is the square of the number of
undirected ones:
$2^{\mathrm{dslots}(N)} = \bigl(2^{\binom{N}{2}}\bigr)^{2}.$
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:double}, $\mathrm{dslots}(N) = 2\binom{N}{2}$, whence
$2^{\mathrm{dslots}(N)} = 2^{2\binom{N}{2}} = (2^{\binom{N}{2}})^2$.
\end{proof}

\begin{theorem}[Monotonicity]
If $M \le N$ then $2^{\binom{M}{2}} \le 2^{\binom{N}{2}}$.
\end{theorem}
\begin{proof}
$\binom{\cdot}{2}$ is monotone in its upper argument, and $2^{(\cdot)}$ is
monotone; compose.
\end{proof}

\section{Superadditivity of Merging}

\begin{theorem}[Merge law]\label{thm:merge}
For all $M, N$,
\[
  \binom{M+N}{2} = \binom{M}{2} + \binom{N}{2} + M N.
\]
Equivalently, fusing an $M$-neuron brain with an $N$-neuron brain creates exactly
$M N$ new cross-synapse slots beyond the two brains' internal slots.
\end{theorem}
\begin{proof}
Multiply both sides by $2$ and apply Theorem~\ref{thm:double}. The left side
becomes $(M+N)(M+N-1)$; the right becomes $M(M-1)+N(N-1)+2MN$. Both expand to
$M^2+N^2+2MN-M-N$. Since the doubled quantities agree and doubling is injective on
integers, the identity holds.
\end{proof}

\begin{remark}[General fusion]
Iterating Theorem~\ref{thm:merge} yields, for neuron counts $N_1,\dots,N_k$,
\[
  \binom{\sum_i N_i}{2} = \sum_i \binom{N_i}{2} + \sum_{i<j} N_i N_j,
\]
exhibiting the combinatorial explosion of cross-connections when many minds are
fused.
\end{remark}

\section{Incompressibility}

An \emph{encoding} is any injective map $\mathrm{enc}$ from connectomes to
$\mathbb{N}$; injectivity is the minimal requirement for lossless, uniquely
decodable storage. We treat the numerical value of a codeword as a proxy for its
length.

\begin{theorem}[Few small codewords]\label{thm:few}
Let $\mathrm{enc}$ be an injective encoding of the connectomes on $N$ neurons into
$\mathbb{N}$, and let $B$ be a threshold. Then
$\#\{c : \mathrm{enc}(c) < B\} \le B.$
\end{theorem}
\begin{proof}
The image of $\{c : \mathrm{enc}(c) < B\}$ under $\mathrm{enc}$ lies in
$\{0,\dots,B-1\}$, of size $B$. Injectivity preserves cardinality, so the set has
size at most $B$ (the pigeonhole principle).
\end{proof}

\begin{theorem}[Most minds are incompressible]
Under any injective encoding of the connectomes on $N$ neurons, the number
receiving a codeword of value $\ge B$ is at least $2^{\binom{N}{2}} - B$. Taking
$B = 2^{\binom{N}{2}-1}$, at least half of all connectomes resist compression
below one bit short of the raw slot count.
\end{theorem}
\begin{proof}
Partition the $2^{\binom{N}{2}}$ connectomes by whether $\mathrm{enc}(c)<B$. By
Theorem~\ref{thm:few} the small class has size $\le B$; the complement has size
$\ge 2^{\binom{N}{2}} - B$. Substituting $B=2^{\binom{N}{2}-1}$ gives exactly half.
\end{proof}

\section{The Physical Ceiling}

\begin{lemma}[Quadratic lower bound]\label{lem:quad}
For $N \ge 1$, $\;(N-1)^2 \le 2\binom{N}{2}.$
\end{lemma}
\begin{proof}
By Theorem~\ref{thm:double}, $2\binom{N}{2} = N(N-1)$. Since $N \ge N-1 \ge 0$,
$N(N-1) \ge (N-1)^2$.
\end{proof}

\begin{theorem}[Neuron bound from storage]\label{thm:nbound}
If $\binom{N}{2} \le I$ where $I = I(R,E)$, then $(N-1)^2 \le 2I.$
\end{theorem}
\begin{proof}
Combine $\binom{N}{2}\le I$ with Lemma~\ref{lem:quad}:
$(N-1)^2 \le 2\binom{N}{2}\le 2I$.
\end{proof}

\begin{theorem}[Explicit neuron ceiling]
Under the hypothesis of Theorem~\ref{thm:nbound}, $\;N \le 1 + \sqrt{2I}.$
\end{theorem}
\begin{proof}
From $(N-1)^2\le 2I$ and $N-1\ge 0$, take square roots: $N-1\le\sqrt{2I}$.
\end{proof}

\begin{corollary}[Scaling law]
The maximum storable neuron count grows only as $\sqrt{I}$, hence only as
$\sqrt{RE}$. Because a mind's information content is quadratic in $N$ while
storage is linear in $RE$, there is a finite, computable ceiling on the size of
any archivable mind.
\end{corollary}

\section{Discussion and Future Directions}

The model abstracts away biological detail to expose the information-theoretic
skeleton of ``mind uploading.'' Every statement is exact and unconditional. Three
robust conclusions survive any refinement: the space of minds grows as
$2^{\Theta(N^2)}$; almost no mind compresses; and physical storage imposes a
square-root ceiling on neuron count. Natural extensions include: a weighted
description-length theorem ($\binom{N}{2}\log_2 w$ bits); average-case entropy
bounds via Kraft--McMillan; the combined directed-weighted state space
$w^{N(N-1)}$; explicit numeric neuron ceilings from concrete SI constants; and
the general fusion hierarchy
$\binom{\sum_i N_i}{2} = \sum_i \binom{N_i}{2} + \sum_{i<j} N_i N_j$.

\end{document}

