from __future__ import annotations
import math

def synapse_slots(n: int) -> int:
    return n * (n - 1) // 2

def connectome_count(n: int, weights: int = 2, directed: bool = False) -> int:
    slots = n * (n - 1) if directed else synapse_slots(n)
    return weights ** slots

def description_bits(n: int, weights: int = 2, directed: bool = False) -> float:
    slots = n * (n - 1) if directed else synapse_slots(n)
    return slots * math.log2(weights)

if __name__ == "__main__":
    for n in (5, 10, 20, 50):
        print(f"N={n}: slots={synapse_slots(n)}, "
              f"Boolean minds=2^{synapse_slots(n)}, "
              f"bits={description_bits(n):.0f}")
    print("Weighted w=4, N=5:", connectome_count(5, weights=4))
    print("Directed squares count (N=4):",
          connectome_count(4, directed=True) == connectome_count(4) ** 2)

from __future__ import annotations
import math

def synapse_slots(n: int) -> int:
    return n * (n - 1) // 2

def bekenstein_bits(radius: float, energy: float,
                    hbar: float = 1.054571817e-34,
                    c: float = 299792458.0) -> float:
    return 2 * math.pi * radius * energy / (hbar * c * math.log(2))

def neuron_ceiling(info_bits: float) -> float:
    return 1 + math.sqrt(2 * info_bits)

if __name__ == "__main__":
    c = 299792458.0
    for R, mass in [(0.1, 1.4), (1.0, 100.0), (6.4e6, 5.97e24)]:
        I = bekenstein_bits(R, mass * c * c)
        print(f"R={R} m, mass={mass} kg -> I={I:.3e} bits, "
              f"N_max <= {neuron_ceiling(I):.3e}")

